css:
/* Molecule 36: change. Mirrors the recoil-player rules for the same parts. */
.pl-change { --d: var(--muted); display: flex; flex-direction: column; gap: 10px; max-width: 420px; }
.pl-change.up { --d: var(--green); } .pl-change.down { --d: var(--red); }
.pl-ans-delta { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; font-family: var(--ds-font-mono); font-variant-numeric: tabular-nums; }
.pl-ans-delta b { font-size: var(--fs-display); line-height: 1; font-weight: 700; letter-spacing: -0.02em; color: var(--d); }
.pl-ans-delta span { font-size: var(--fs-label); color: var(--text-secondary); }
.pl-move { display: block; }
.pl-move-track { display: block; position: relative; height: 14px; }
.pl-move-track::before { content: ""; position: absolute; left: 0; right: 0; top: 6px; height: 2px; border-radius: var(--ds-r-pill); background: var(--border); }
.pl-move-seg { position: absolute; top: 6px; height: 2px; background: var(--d); }
.pl-move-tail { position: absolute; top: 3px; width: 2px; height: 8px; margin-left: -1px; background: var(--text-secondary); }
.pl-move-head { position: absolute; top: 1px; width: 12px; height: 12px; background: var(--d); }
.pl-change.up .pl-move-head { margin-left: -11px; clip-path: polygon(0 0, 100% 50%, 0 100%); }
.pl-change.down .pl-move-head { margin-left: -1px; clip-path: polygon(100% 0, 0 50%, 100% 100%); }
.pl-change.flat .pl-move-head { margin-left: -5px; width: 10px; height: 10px; top: 2px; border-radius: 50%; }
.sp-state .pl-ans-delta b { font-size: var(--fs-headline); }
